<template><view class="growth-page" :class="{'motion-reduced':reducedMotion}"><view class="growth-hero"><text class="growth-eyebrow">A MOMENT FOR YOU</text><text class="growth-title">把这一刻，留给自己</text><text class="growth-subtitle">完成比完美重要。可以记录感受，也可以直接继续。</text></view><view v-if="error" class="growth-error">{{error}}</view><view class="growth-card"><text class="growth-card-title">给创作取个名字</text><input v-model="form.title" class="growth-input" maxlength="100" placeholder="例如：慢慢展开的春天"/><text class="growth-card-title">开始前的感受（选填）</text><view class="growth-row"><view v-for="(m,i) in moods" :key="m" :class="['growth-choice',{selected:form.beforeMood===i+1}]" @click="form.beforeMood=form.beforeMood===i+1?null:i+1">{{m}}</view></view><text class="growth-card-title">现在的感受</text><view class="growth-row"><view v-for="(m,i) in moods" :key="m" :class="['growth-choice',{selected:form.afterMood===i+1}]" @click="form.afterMood=i+1">{{m}}</view></view><input v-model="form.emotion" class="growth-input" maxlength="30" placeholder="一个情绪词，例如：安定（选填）"/><textarea v-model="form.note" class="growth-input growth-textarea" maxlength="500" placeholder="创作时注意到了什么？（选填）"/><checkbox-group @change="form.consent=$event.detail.value.length>0"><label class="growth-consent"><checkbox value="yes" :checked="form.consent" color="#2f7566"/>同意加密保存本次感受，仅在我的成长记录中展示。</label></checkbox-group><button class="growth-button" :disabled="busy||!form.consent||!form.afterMood||!form.title.trim()" @click="save">保存感受</button></view><button class="growth-button secondary" :disabled="busy" @click="publish">拍照 / 发布作品</button><button class="growth-button secondary" :disabled="busy" @click="home">返回首页</button><text class="growth-foot">本系统不能替代专业心理咨询</text></view></template>
<script setup>
import {useInteraction} from '../../composables/useInteraction'
const {reducedMotion}=useInteraction()

import{ref,reactive}from'vue';import{onLoad}from'@dcloudio/uni-app';import{request}from'../../utils/request';const busy=ref(false),error=ref('');let projectId='';const moods=['低落','偏低','平静','不错','开心'];const form=reactive({sessionId:'',title:'',beforeMood:null,afterMood:0,emotion:'',note:'',consent:false});onLoad(o=>{form.sessionId=o.sessionId||'';projectId=o.projectId||''});async function save(){if(busy.value)return;busy.value=true;try{await request({url:'/api/growth/reflection',method:'POST',data:form});uni.showToast({title:'已保存',icon:'success'});uni.redirectTo({url:'/pages/journey/index'})}catch(e){error.value=e.message}finally{busy.value=false}}function publish(){uni.redirectTo({url:'/pages/work/publish?sessionId='+form.sessionId+'&projectId='+projectId})}function home(){uni.switchTab({url:'/pages/home/index'})}
</script><style src="../../styles/growth.css"></style><style scoped>.growth-choice{font-size:23rpx;padding:16rpx 12rpx;flex:1;text-align:center}.growth-row{gap:8rpx;margin-bottom:28rpx}</style>
